<?php
/** Native record field isolation, static assets and dormant-data safety. */
if ( ! defined( 'WP_CLI' ) || ! WP_CLI || home_url() !== getenv( 'MRN_STACK_TEST_HOME' ) || ! str_ends_with( (string) wp_parse_url( home_url(), PHP_URL_HOST ), '.localhost' ) || ! current_user_can( 'manage_options' ) ) { throw new RuntimeException( 'An explicitly selected local administrator runtime is required.' ); }
$checks = array(); $expect = static function ( $ok, $label ) use ( &$checks ) { if ( ! $ok ) { throw new RuntimeException( esc_html( $label ) ); } $checks[] = $label; };
$layouts = array_column( acf_get_field( 'field_mrn_page_content_rows' )['layouts'], null, 'name' ); $fields = array_column( $layouts['showcase']['sub_fields'], null, 'name' ); $items = array_column( $fields['showcase_items']['sub_fields'], null, 'name' );
$expect( isset( $fields['showcase_presentation']['choices']['split-records'] ) && 'standard' === $fields['showcase_presentation']['default_value'], 'Record presentation is optional; Standard remains the default' );
$expect( 12 === $fields['showcase_items']['max'] && 30 === $items['text_tags']['max'], 'Record and tag capacities are bounded at twelve and thirty' );
$expect( ! mrn_base_stack_showcase_item_row_has_content( array( 'record_heading_tag' => 'h3' ) ), 'A default heading selector cannot retain an empty Showcase placeholder' );
$expect( mrn_base_stack_showcase_item_row_has_content( array( 'record_heading_tag' => 'h3', 'record_heading' => 'Keep this record' ) ), 'A populated record remains content when its heading selector is ignored' );
$expect( 30 === acf_get_field_type( 'repeater' )->get_rest_schema( $items['text_tags'] )['maxItems'], 'REST schema exposes the same tag capacity' );
$body_fields = array_column( $layouts['body_text']['sub_fields'], null, 'name' ); $expect( 5 === $body_fields['text_tags']['max'], 'Existing Body Text tag capacity stays unchanged' );
$factory = mrn_base_stack_get_showcase_record_fields( 'field_mrn_test_records' ); $keys = array_column( $factory, 'key' ); $expect( count( $keys ) === count( array_unique( $keys ) ), 'Responsive record tags and shared tag styles never reuse an ACF key' );
$other = array_column( mrn_base_stack_get_showcase_record_item_fields( 'field_mrn_other_records_record', 'field_mrn_other_presentation' ), null, 'name' ); foreach ( array( 'record_heading', 'record_heading_tag', 'record_content', 'text_tags' ) as $name ) { $expect( isset( $items[ $name ], $other[ $name ] ) && $items[ $name ]['key'] !== $other[ $name ]['key'], 'Record content factory keys stay isolated: ' . $name ); }
$row = array( 'acf_fc_layout' => 'showcase', 'showcase_presentation' => 'split-records', 'records_title_size' => 'var(--site-text-h3-size)', 'records_title_line_height' => '1.2', 'records_title_color' => 'burgundy', 'records_item_padding' => '100px', 'showcase_items' => array( array( 'record_heading' => 'Keep <em>literal title</em>', 'record_heading_tag' => 'h3', 'record_content' => '<p>Keep this rich <strong>copy</strong> and <a href="/keep/?a=1&amp;b=2">link</a>.</p>', 'text_tags' => array( array( 'text' => 'A & B', 'url' => '' ) ), 'links' => array( array( 'link' => array( 'title' => 'Choose & continue', 'url' => home_url( '/keep/?a=1&b=2' ), 'target' => '_blank' ) ) ) ) ) );
$id = wp_insert_post( array( 'post_type' => 'page', 'post_status' => 'draft', 'post_title' => 'Owned native record safety proof' ), true ); $expect( ! is_wp_error( $id ) && $id > 0, 'Owned proof created' );
try {
	update_field( 'field_mrn_page_content_rows', wp_slash( array( $row ) ), $id ); acf_flush_value_cache( $id, 'page_content_rows' ); $saved = get_field( 'page_content_rows', $id )[0];
	$expect( 1 === count( $saved['showcase_items'] ) && $row['showcase_items'][0]['record_heading'] === $saved['showcase_items'][0]['record_heading'], 'A valid record without an image survives placeholder pruning' );
	$expect( $row['showcase_items'][0]['record_content'] === get_post_meta( $id, 'page_content_rows_0_showcase_items_0_record_content', true ), 'Rich copy, wording and complete query link remain exact' );
	$expect( ! mrn_base_stack_get_front_end_component_needs_for_post( $id )['presentation'], 'Static records request no presentation payload' );
	$style = mrn_base_stack_get_showcase_record_contract( $row )['attributes']['style']; foreach ( array( '--mrn-records-title-size:var(--site-text-h3-size)', '--mrn-records-title-line-height:1.2', '--mrn-records-title-color:var(--site-color-burgundy)', '--mrn-records-item-padding:100px' ) as $part ) { $expect( str_contains( $style, $part ), 'Validated record style: ' . $part ); }
	foreach ( array( '-1px', '1px;color:red', 'var(--unknown)', array( '12px' ) ) as $bad ) { $contract = mrn_base_stack_get_showcase_record_contract( array( 'showcase_presentation' => 'split-records', 'records_title_size' => $bad, 'records_title_color' => $bad, 'records_item_padding' => $bad ) ); $expect( '' === $contract['attributes']['style'], 'Invalid values cannot emit arbitrary CSS' ); }
	$expect( ! mrn_base_stack_get_showcase_record_contract( array_replace( $row, array( 'showcase_presentation' => 'standard' ) ) )['attributes'], 'Unselected records ignore dormant styles' );
	ob_start(); mrn_base_stack_render_builder_rows( array( $saved ), $id, 'page_content_rows' ); $html = ob_get_clean();
	$expect( str_contains( $html, 'Keep &lt;em&gt;literal title&lt;/em&gt;' ) && str_contains( $html, '<strong>copy</strong>' ) && str_contains( $html, 'A &amp; B' ), 'Plain title/tags are escaped and rich content stays rich' );
	$expect( str_contains( $html, 'target="_blank" rel="noopener noreferrer"' ) && str_contains( $html, 'aria-hidden="true" focusable="false"' ) && ! str_contains( $html, 'tabindex="0"' ), 'Independent action secures new tabs and keeps its arrow decorative' );
	$expect( str_contains( $html, '<ul class="mrn-text-tags' ) && ! str_contains( $html, '<script' ), 'Structured tags retain list semantics without JavaScript' );
	$unsafe = $saved; $unsafe['showcase_items'][0]['links'][0]['link']['url'] = 'javascript:alert(1)'; ob_start(); mrn_base_stack_render_builder_rows( array( $unsafe ), $id, 'page_content_rows' ); $bad_html = ob_get_clean(); $expect( ! str_contains( $bad_html, 'href="javascript:' ), 'Unsafe action protocols cannot execute' );
	$standard = $saved; $standard['showcase_presentation'] = 'standard'; ob_start(); mrn_base_stack_render_builder_rows( array( $standard ), $id, 'page_content_rows' ); $old_html = ob_get_clean(); $expect( ! str_contains( $old_html, 'literal title' ) && ! str_contains( $old_html, 'has-showcase-records' ), 'Standard Showcase does not render dormant record copy' );
	update_field( 'field_mrn_page_content_rows', array( array( 'acf_fc_layout' => 'card', 'card_presentation' => 'pricing', 'card_items' => array( array( 'card_label' => 'Static pricing' ) ) ) ), $id ); clean_post_cache( $id );
	$expect( ! mrn_base_stack_get_front_end_component_needs_for_post( $id )['presentation'], 'Static pricing also avoids presentation payload' );
} finally { wp_delete_post( $id, true ); }
$expect( null === get_post( $id ), 'Owned proof removed' ); WP_CLI::line( wp_json_encode( array( 'result' => 'passed', 'count' => count( $checks ), 'checks' => $checks, 'candidate_only' => true ), JSON_PRETTY_PRINT ) );
